      const max = this.maxForecast;
      const range = Math.max(1, max - min);
      const lowCutoff = min + range / 3;
      const highCutoff = min + 2 * range / 3;
      if (value <= lowCutoff) return 'Low';
      if (value >= highCutoff) return 'High';
      return 'Mid';
